import React, { useState, useEffect } from 'react';
import { FaUserCheck, FaUserTimes, FaCalendarDay } from 'react-icons/fa';

const Asistencia = () => {
  const [claseSeleccionada, setClaseSeleccionada] = useState('');
  const [estudiantes, setEstudiantes] = useState([]);
  const [fecha, setFecha] = useState(new Date().toISOString().split('T')[0]);

  // Datos de ejemplo
  useEffect(() => {
    if (claseSeleccionada) {
      const mockEstudiantes = [
        { id: 1, nombre: 'Juan Pérez', asistencia: null },
        { id: 2, nombre: 'María Gómez', asistencia: null },
        { id: 3, nombre: 'Carlos Ruiz', asistencia: null },
      ];
      setEstudiantes(mockEstudiantes);
    }
  }, [claseSeleccionada]);

  const handleAsistenciaChange = (id, valor) => {
    setEstudiantes(estudiantes.map(est => 
      est.id === id ? { ...est, asistencia: valor } : est
    ));
  };

  const guardarAsistencia = () => {
    console.log('Asistencia guardada:', estudiantes);
    // Aquí iría la lógica para enviar al backend
    alert('Asistencia registrada correctamente');
  };

  return (
    <div className="docente-content">
      <h2><FaUserCheck /> Registro de Asistencia</h2>
      
      <div className="filtros">
        <div className="form-group">
          <label>Seleccione Clase:</label>
          <select 
            value={claseSeleccionada} 
            onChange={(e) => setClaseSeleccionada(e.target.value)}
          >
            <option value="">-- Seleccionar --</option>
            <option value="matematicas">Matemáticas 10A</option>
            <option value="fisica">Física 11B</option>
            <option value="quimica">Química 9C</option>
          </select>
        </div>
        
        <div className="form-group">
          <label>Fecha:</label>
          <div className="date-input">
            <FaCalendarDay />
            <input 
              type="date" 
              value={fecha} 
              onChange={(e) => setFecha(e.target.value)} 
            />
          </div>
        </div>
      </div>

      {claseSeleccionada && (
        <>
          <div className="table-container">
            <table>
              <thead>
                <tr>
                  <th>Estudiante</th>
                  <th>Asistencia</th>
                </tr>
              </thead>
              <tbody>
                {estudiantes.map((est) => (
                  <tr key={est.id}>
                    <td>{est.nombre}</td>
                    <td className="asistencia-options">
                      <label>
                        <input
                          type="radio"
                          name={`asistencia-${est.id}`}
                          checked={est.asistencia === true}
                          onChange={() => handleAsistenciaChange(est.id, true)}
                        /> Presente
                      </label>
                      <label>
                        <input
                          type="radio"
                          name={`asistencia-${est.id}`}
                          checked={est.asistencia === false}
                          onChange={() => handleAsistenciaChange(est.id, false)}
                        /> Ausente
                      </label>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          
          <button 
            className="btn-save" 
            onClick={guardarAsistencia}
            disabled={!estudiantes.some(e => e.asistencia !== null)}
          >
            Guardar Asistencia
          </button>
        </>
      )}
    </div>
  );
};

export default Asistencia;
